import sys

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        n = int(data)
    except ValueError:
        return
    if n <= 0:
        return
    fib = []
    a, b = 0, 1
    for _ in range(n):
        fib.append(str(a))
        a, b = b, a + b
    sys.stdout.write(' '.join(fib))

if __name__ == "__main__":
    main()
